<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Message={id:string;body:string;author_name:string;created_at:string};type Thread={id:string;title:string;kind:string;unread:boolean;messages:Message[]};
 let threads=$state<Thread[]>([]),selected=$state(''),body=$state(''),busy=$state(false),error=$state('');let active=$derived(threads.find(x=>x.id===selected)??threads[0]);
 async function load(){try{threads=await request<Thread[]>('/v1/collaboration');if(!selected)selected=threads[0]?.id??'';}catch(e){error=e instanceof Error?e.message:'Inbox tidak dapat dimuat.';}}
 async function send(){if(!active||!body.trim())return;busy=true;try{await request(`/v1/collaboration/${active.id}/messages`,{method:'POST',body:JSON.stringify({body})});body='';await load();}finally{busy=false;}}
 onMount(()=>{void load();const timer=setInterval(load,15000);return()=>clearInterval(timer);});
</script>
<main class="workspace-page"><PageHeader title="Collaboration inbox" description="Pesan ruang kerja Anda diperbarui otomatis setiap 15 detik." backHref="/app/today"/>{#if error}<p class="alert">{error}</p>{/if}<div class="layout"><nav class="panel">{#each threads as item (item.id)}<button class:active={active?.id===item.id} onclick={()=>selected=item.id}><strong>{item.title}</strong><small>{item.kind}{item.unread?' · baru':''}</small></button>{:else}<p class="muted">Belum ada ruang.</p>{/each}</nav><section class="panel">{#if active}<header><h2>{active.title}</h2><RefreshButton onclick={load} label="Muat ulang"/></header><div class="messages">{#each active.messages as message (message.id)}<article><strong>{message.author_name}</strong><p>{message.body}</p><small>{new Date(message.created_at).toLocaleString('id-ID')}</small></article>{:else}<p class="muted">Belum ada pesan.</p>{/each}</div><form novalidate onsubmit={(e)=>{e.preventDefault();void send();}}><textarea bind:value={body} placeholder="Tulis pesan" required></textarea><button disabled={busy}>Kirim</button></form>{/if}</section></div></main>
<style>.workspace-page,.layout{display:grid;gap:12px}.layout{grid-template-columns:280px 1fr}.panel{padding:16px;border-radius:var(--radius)}nav{display:grid;align-content:start;gap:6px}nav button{text-align:left;background:var(--surface-alt);color:var(--text)}nav button.active{outline:1px solid var(--accent)}small{display:block;color:var(--muted);font-size:12px}.messages{display:grid;gap:8px;max-height:440px;overflow:auto}article{padding:10px;border:1px solid var(--line);border-radius:var(--radius)}article p{margin:5px 0}form{display:grid;gap:8px;margin-top:12px}.alert{color:var(--danger)}@media(max-width:720px){.layout{grid-template-columns:1fr}}</style>
